import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline
cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_runtime.h>
// Max reduction over dim=1 of a contiguous (B, D1, D2) float32 tensor.
// Optimization: map one thread to one output column so threads in a warp
// read consecutive columns for every row step, making global loads coalesced
// even when D2 is not divisible by 4.
__global__ void max_reduce_dim1_kernel(const float* __restrict__ x,
                                       float* __restrict__ out,
                                       int D1, int D2) {
    const int b = blockIdx.y;
    const int j = blockIdx.x * blockDim.x + threadIdx.x;
    if (j >= D2) return;
    const float* p = x + (size_t)b * D1 * D2 + j;
    float m = -INFINITY;
    for (int i = 0; i < D1; ++i) {
        m = fmaxf(m, p[(size_t)i * D2]);
    }
    out[(size_t)b * D2 + j] = m;
}
torch::Tensor max_reduce_dim1(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "input must be CUDA");
    TORCH_CHECK(x.scalar_type() == torch::kFloat32, "input must be float32");
    TORCH_CHECK(x.dim() == 3, "input must be 3D");
    auto xc = x.contiguous();
    const int B  = (int)xc.size(0);
    const int D1 = (int)xc.size(1);
    const int D2 = (int)xc.size(2);
    auto out = torch::empty({B, D2}, xc.options());
    const int threads = 256;
    dim3 grid((D2 + threads - 1) / threads, B);
    max_reduce_dim1_kernel<<<grid, threads, 0, at::cuda::getCurrentCUDAStream()>>>(
        xc.data_ptr<float>(), out.data_ptr<float>(), D1, D2);
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return out;
}
"""
cpp_src = "torch::Tensor max_reduce_dim1(torch::Tensor x);"
_mod = load_inline(
    name="max_reduce_dim1_ext",
    cpp_sources=cpp_src,
    cuda_sources=cuda_src,
    functions=["max_reduce_dim1"],
    verbose=False,
)
class ModelNew(nn.Module):
    """
    Model that performs Max reduction over a specific dimension using a
    custom CUDA kernel (specialized for reduction over dim=1 of a 3D tensor).
    """
    def __init__(self, dim: int):
        super(ModelNew, self).__init__()
        self.dim = dim
    def forward(self, x: torch.Tensor) -> torch.Tensor:
        dim = self.dim if self.dim >= 0 else self.dim + x.dim()
        if x.is_cuda and x.dim() == 3 and dim == 1 and x.dtype == torch.float32:
            return _mod.max_reduce_dim1(x)
        return torch.max(x, dim=self.dim)[0]

