import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_runtime.h>

// Max reduction over dim=1 of a contiguous (B, D1, D2) float32 tensor.
// Each thread computes 4 consecutive output elements (vectorized float4 loads).
// Threads within a warp read consecutive memory addresses for every reduction
// step, so all global loads are fully coalesced.
__global__ void max_reduce_dim1_kernel(const float* __restrict__ x,
                                       float* __restrict__ out,
                                       int D1, int D2) {
    const int b = blockIdx.y;
    const int j = (blockIdx.x * blockDim.x + threadIdx.x) * 4;
    if (j >= D2) return;

    const float* base = x + (size_t)b * D1 * D2 + j;

    if (((D2 & 3) == 0) && (j + 3 < D2)) {
        // Aligned vectorized path: only legal when D2 % 4 == 0, so that
        // every row offset b*D1*D2 + i*D2 + j and out offset b*D2 + j
        // is a multiple of 4 floats (16 bytes).
        float m0 = -INFINITY, m1 = -INFINITY, m2 = -INFINITY, m3 = -INFINITY;
        for (int i = 0; i < D1; ++i) {
            const float4 v = *reinterpret_cast<const float4*>(base + (size_t)i * D2);
            m0 = fmaxf(m0, v.x);
            m1 = fmaxf(m1, v.y);
            m2 = fmaxf(m2, v.z);
            m3 = fmaxf(m3, v.w);
        }
        *reinterpret_cast<float4*>(out + (size_t)b * D2 + j) = make_float4(m0, m1, m2, m3);
    } else {
        // Scalar path for unaligned D2 and/or the remaining (< 4) columns.
        const int rem = min(4, D2 - j);
        for (int k = 0; k < rem; ++k) {
            const float* p = base + k;
            float m = -INFINITY;
            for (int i = 0; i < D1; ++i) {
                m = fmaxf(m, p[(size_t)i * D2]);
            }
            out[(size_t)b * D2 + j + k] = m;
        }
    }
}

torch::Tensor max_reduce_dim1(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "input must be CUDA");
    TORCH_CHECK(x.scalar_type() == torch::kFloat32, "input must be float32");
    TORCH_CHECK(x.dim() == 3, "input must be 3D");

    auto xc = x.contiguous();
    const int B  = (int)xc.size(0);
    const int D1 = (int)xc.size(1);
    const int D2 = (int)xc.size(2);

    auto out = torch::empty({B, D2}, xc.options());

    const int threads = 256;
    const int nvec = (D2 + 3) / 4;
    dim3 grid((nvec + threads - 1) / threads, B);

    max_reduce_dim1_kernel<<<grid, threads, 0, at::cuda::getCurrentCUDAStream()>>>(
        xc.data_ptr<float>(), out.data_ptr<float>(), D1, D2);
    C10_CUDA_KERNEL_LAUNCH_CHECK();

    return out;
}
"""

